import{useEffect,useState}from'react';import{LifeBuoy,RefreshCw,Send}from'lucide-react';import{createSupportTicket,listSupportTickets}from'../../lib/practiceOperationsApi';
const TYPES=['TECHNICAL','ACCOUNT','BILLING','DATA','MARKETPLACE','INTEGRATION','FEATURE_REQUEST','OTHER'];
export function ExternalSupport(){const[items,setItems]=useState([]),[state,setState]=useState('loading'),[error,setError]=useState(''),[form,setForm]=useState({ticket_type:'TECHNICAL',subject:'',description:''});const load=async()=>{setState('loading');setError('');try{const d=await listSupportTickets();setItems(d.items||[]);setState((d.items||[]).length?'ready':'empty')}catch(e){setError(e.message);setState('error')}};useEffect(()=>{load()},[]);const submit=async e=>{e.preventDefault();setState('saving');try{await createSupportTicket({...form,context:{module:'Support',route:location.pathname,build_sha:process.env.NEXT_PUBLIC_GIT_SHA||'unknown'}});setForm({...form,subject:'',description:''});await load()}catch(x){setError(x.message);setState('error')}};return <section className="space-y-5"><header><h2 className="text-2xl font-bold text-slate-950">Platform Support</h2><p className="text-sm text-slate-600">Consultant and practice support — not client clinical support. Never include passwords, tokens, or clinical records.</p></header><form onSubmit={submit} className="grid gap-3 rounded-2xl border bg-white p-5 sm:grid-cols-2"><select aria-label="Support category" value={form.ticket_type} onChange={e=>setForm({...form,ticket_type:e.target.value})} className="min-h-11 rounded-xl border px-3">{TYPES.map(x=><option key={x}>{x}</option>)}</select><input required minLength="3" placeholder="Subject" value={form.subject} onChange={e=>setForm({...form,subject:e.target.value})} className="min-h-11 rounded-xl border px-3"/><textarea required minLength="3" placeholder="Describe the platform issue without secrets" value={form.description} onChange={e=>setForm({...form,description:e.target.value})} className="min-h-28 rounded-xl border p-3 sm:col-span-2"/><button disabled={state==='saving'} className="inline-flex min-h-11 items-center justify-center gap-2 rounded-xl bg-slate-950 px-4 font-semibold text-white"><Send size={16}/>Submit ticket</button></form>{state==='loading'?<p>Loading support tickets…</p>:state==='error'?<div role="alert" className="rounded-xl border border-red-200 bg-red-50 p-4">Support tickets unavailable: {error}<button onClick={load} className="ml-3"><RefreshCw size={16}/></button></div>:state==='empty'?<div className="rounded-xl border border-dashed p-6 text-center"><LifeBuoy className="mx-auto"/><p>No support tickets yet.</p></div>:<div className="space-y-2">{items.map(x=><article key={x.id} className="rounded-xl border bg-white p-4"><div className="flex justify-between"><strong>{x.subject}</strong><span>{x.priority} · {x.status}</span></div><p className="text-sm text-slate-500">{x.ticket_type}</p></article>)}</div>}</section>}
